      role1 = 2143000,
      role2 = 201106,
      role3 = 201204,
      role5 = 2143404,
      sentence = "At first, some of the experimental drugs really worked. They fixed the Evolvers' gene defects, at least for a while. The subjects showed huge boosts in their abilities.",
