      renwu = "npc",
      role1 = 2143000,
      role2 = 201106,
      role3 = 201204,
      role5 = 2143404,
      sentence = "However, the enhancement didn't come without a cost. It caused a rapid accumulation of Evol energy in the subjects' bodies... and that quickly drained their life away.",
